{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Encainide absolute oral bioavailability in normal subjects was 32 ± 7%, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Niraparib absolute oral bioavailability was 72.7% (90% CI 61.69–83.40) in patients, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Cilomilast absolute oral bioavailability was 96% (range 92–102%) in healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All numeric absolute or ordinary-condition oral bioavailability records among the transferred evidence are ≥20%, with representative values from about 32% to 96%. Qualitative reports of good, excellent, or near-complete bioavailability are consistent but were not used as primary evidence.",
  "evidence_gaps": [
    "Several records are qualitative (good, excellent, near-complete) without numeric F values, providing only weak supportive direction.",
    "One encainide record reports a wide patient range (7–82%) and a qualitative 'low' description, but the strongest absolute numeric records in normal subjects are ≥20%.",
    "Some numeric records were obtained under altered conditions such as cirrhosis, fed state, or pediatric populations, making them less condition-matched though still above threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

